#include <iostream>

int main() {
    int zahl = 3;

    std::cout << "Sequenz" << std::endl;
    if (zahl > 2) {
        std::cout << "Entscheidung" << std::endl;
    }
    for (int i = 0; i < 3; ++i) {
        std::cout << "Schleife " << i << std::endl;
    }
    return 0;
}

